// Performs HTTP GET requests and aggregates the results into a report
class worker : public std::enable_shared_from_this<worker> {
    enum {
        // Use a small timeout to keep things lively
        timeout = 5,
    };

    crawl_report& report_;
    net::strand<webcpp::asio::io_context::executor_type> ex_;
    webcpp::asio::ip::tcp::resolver resolver_;
    beast::tcp_stream stream_;
    beast::flat_buffer buffer_;  // (Must persist between reads)
    http::request<http::empty_body> req_;
    http::response<http::string_body> res_;

public:
    worker(worker&&) = default;

    // Resolver and socket require an io_context
    worker(crawl_report& report, webcpp::asio::io_context& ioc)
        : report_(report), ex_(net::make_strand(ioc.get_executor())), resolver_(ex_), stream_(ex_) {
        // Set up the common fields of the request
        req_.version(11);
        req_.method(http::verb::get);
        req_.target("/");
    }

    // Start the asynchronous operation
    void run() { do_get_host(); }

    void do_get_host() {
        // Grab another host
        const auto* const host = report_.get_host();

        // nullptr means no more work
        if (host == nullptr) {
            return;
        }

        // The Host HTTP field is required
        req_.set(http::field::host, host);

        // Set up an HTTP GET request message
        // Look up the domain name
        resolver_.async_resolve(host, webcpp_fixture::port(),
                                beast::bind_front_handler(&worker::on_resolve, shared_from_this()));
    }

    // Value parameters retain the upstream callback and coroutine ownership contract.
    // NOLINTNEXTLINE(performance-unnecessary-value-param)
    void on_resolve(beast::error_code ec, webcpp::asio::ip::tcp::resolver::results_type results) {
        if (ec) {
            report_.aggregate([](crawl_report& rep) { ++rep.resolve_failures; });
            do_get_host();
            return;
        }

        // Set a timeout on the operation
        stream_.expires_after(std::chrono::seconds(10));

        // Make the connection on the IP address we get from a lookup
        stream_.async_connect(results,
                              beast::bind_front_handler(&worker::on_connect, shared_from_this()));
    }

    void on_connect(beast::error_code ec,
                    // Value parameters retain the upstream callback and coroutine ownership
                    // contract. NOLINTNEXTLINE(performance-unnecessary-value-param)
                    webcpp::asio::ip::tcp::resolver::results_type::endpoint_type /*unused*/) {
        if (ec) {
            report_.aggregate([](crawl_report& rep) { ++rep.connect_failures; });
            do_get_host();
            return;
        }

        // Set a timeout on the operation
        stream_.expires_after(std::chrono::seconds(10));

        // Send the HTTP request to the remote host
        http::async_write(stream_, req_,
                          beast::bind_front_handler(&worker::on_write, shared_from_this()));
    }

    void on_write(beast::error_code ec, std::size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if (ec) {
            report_.aggregate([](crawl_report& rep) { ++rep.write_failures; });
            do_get_host();
            return;
        }

        // Receive the HTTP response
        res_ = {};
        http::async_read(stream_, buffer_, res_,
                         beast::bind_front_handler(&worker::on_read, shared_from_this()));
    }

    void on_read(beast::error_code ec, std::size_t bytes_transferred) {
        boost::ignore_unused(bytes_transferred);

        if (ec) {
            report_.aggregate([](crawl_report& rep) { ++rep.read_failures; });
            do_get_host();
            return;
        }

        auto const code = res_.result_int();
        report_.aggregate([code](crawl_report& rep) {
            ++rep.success;
            ++rep.status_codes[code];
        });

        // Gracefully close the socket
        stream_.socket().shutdown(tcp::socket::shutdown_both, ec);
        stream_.close();

        // If we get here then the connection is closed gracefully

        do_get_host();
    }
};

class timer {
    using clock_type = chrono::system_clock;

    clock_type::time_point when_;

public:
    using duration = clock_type::duration;

    timer() : when_(clock_type::now()) {}

    [[nodiscard]] duration elapsed() const { return clock_type::now() - when_; }
};

// The process entry point retains its standard char** argv signature.
// NOLINTNEXTLINE(misc-const-correctness)
int application_main(int argc, char** argv) {
    // Check command line arguments.
    if (argc != 2) {
        std::cerr << "Usage: http-crawl <threads>\n" << "Example:\n" << "    http-crawl 100\n";
        return EXIT_FAILURE;
    }
    [[maybe_unused]] auto const threads = std::max<int>(1, webcpp_fixture::integer(argv[1]));

    // The io_context is used to aggregate the statistics
    webcpp::asio::io_context ioc;

    // The report holds the aggregated statistics
    crawl_report report{ioc};

    // This mutable object is passed through the upstream asynchronous or stream interface.
    // NOLINTNEXTLINE(misc-const-correctness)
    timer t;

    // Each worker preserves the original crawl state machine on one explicit executor.
    for (int index = 0; index < threads; ++index) {
        std::make_shared<worker>(report, ioc)->run();
    }
    ioc.run();  // lint-run: advances every crawl worker and its aggregate report

    std::cout << "Elapsed time:    " << chrono::duration_cast<chrono::seconds>(t.elapsed()).count()
              << " seconds\n";
    std::cout << report;

    return EXIT_SUCCESS;
}

