int main() {
    const auto port = emscripten::val::global("location")["port"].as<std::string>();
    if (setenv("WEBCPP_BEAST_FIXTURE_HOST", "127.0.0.1", 1) != 0) {
        return 1;
    }
    if (setenv("WEBCPP_BEAST_FIXTURE_PORT", port.c_str(), 1) != 0) {
        return 1;
    }
    {
        std::vector<std::string> storage{"http-crawl", "2"};
        std::vector<char*> arguments;
        arguments.reserve(storage.size());
        for (auto& value : storage) {
            arguments.push_back(value.data());
        }
        // This mutable object is passed through the upstream asynchronous or stream interface.
        // NOLINTNEXTLINE(misc-const-correctness)
        std::ostringstream output;
        auto* original = std::cout.rdbuf(output.rdbuf());
        const auto result = application_main(static_cast<int>(arguments.size()), arguments.data());
        std::cout.rdbuf(original);
        std::cout << output.str();
        if (result != 0 || output.str().find("Success : 3") == std::string::npos) {
            return 1;
        }
    }
    std::cout << "application http-crawl: passed\n";
    return 0;
}
